                    if best_ins is not None and rem_delta + best_ins < -1e-12:
                        new_ra = ra[:ia] + ra[ia + 1:]
                        new_rb = rb[:best_pos] + [x] + rb[best_pos:]
                        routes[a] = new_ra
                        routes[b] = new_rb
                        changed = True
                        break
                if changed:
                    break
            if changed:
                break
        routes = [r for r in routes if r]
        routes = [two_opt(r) for r in routes]

    routes.sort(key=lambda r: (r[0] if r else -1, len(r), tuple(r)))
    return routes
